1	package external
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"fmt"
8		"io"
9		"os/exec"
10		"strconv"
11		"strings"
12		"time"
13	
14		"github.com/entireio/cli/cmd/entire/cli/agent"
15		"github.com/entireio/cli/cmd/entire/cli/agent/types"
16		"github.com/entireio/cli/cmd/entire/cli/paths"
17		"github.com/entireio/cli/cmd/entire/cli/versioninfo"
18	)
19	
20	// defaultRunTimeout is the maximum time an external binary call may take when
21	// the caller provides a context without a deadline.
22	var defaultRunTimeout = 30 * time.Second //nolint:gochecknoglobals // overridable for testing
23	
24	// Agent implements agent.Agent by delegating to an external binary.
25	// Each method invokes a subcommand on the binary and parses the JSON response.
26	type Agent struct {
27		binaryPath string
28		info       *InfoResponse
29	}
30	
31	// New creates an Agent by calling the binary's "info" subcommand
32	// to cache its metadata. Returns an error if the binary cannot be invoked or returns
33	// invalid/incompatible protocol data. The provided context bounds the "info" call;
34	// pass a context with a deadline to limit how long discovery waits for each binary.
35	func New(ctx context.Context, binaryPath string) (*Agent, error) {
36		ea := &Agent{binaryPath: binaryPath}
37	
38		stdout, err := ea.run(ctx, nil, "info")
39		if err != nil {
40			return nil, fmt.Errorf("info: %w", err)
41		}
42	
43		var info InfoResponse
44		if err := json.Unmarshal(stdout, &info); err != nil {
45			return nil, fmt.Errorf("info: invalid JSON: %w", err)
46		}
47	
48		if info.ProtocolVersion != ProtocolVersion {
49			return nil, fmt.Errorf("protocol version mismatch: binary reports %d, expected %d",
50				info.ProtocolVersion, ProtocolVersion)
51		}
52	
53		ea.info = &info
54		return ea, nil
55	}
56	
57	// Info returns the cached info response.
58	func (e *Agent) Info() *InfoResponse {
59		return e.info
60	}
61	
62	// --- Agent interface: Identity ---
63	
64	func (e *Agent) Name() types.AgentName {
65		return types.AgentName(e.info.Name)
66	}
67	
68	func (e *Agent) Type() types.AgentType {
69		return types.AgentType(e.info.Type)
70	}
71	
72	func (e *Agent) Description() string {
73		return e.info.Description
74	}
75	
76	func (e *Agent) IsPreview() bool {
77		return e.info.IsPreview
78	}
79	
80	func (e *Agent) DetectPresence(ctx context.Context) (bool, error) {
81		stdout, err := e.run(ctx, nil, "detect")
82		if err != nil {
83			return false, fmt.Errorf("detect: %w", err)
84		}
85		var resp DetectResponse
86		if err := json.Unmarshal(stdout, &resp); err != nil {
87			return false, fmt.Errorf("detect: invalid JSON: %w", err)
88		}
89		return resp.Present, nil
90	}
91	
92	func (e *Agent) ProtectedDirs() []string {
93		return e.info.ProtectedDirs
94	}
95	
96	func (e *Agent) ProtectedFiles() []string {
97		return e.info.ProtectedFiles
98	}
99	
100	// --- Agent interface: Transcript Storage ---
101	
102	func (e *Agent) ReadTranscript(sessionRef string) ([]byte, error) {
103		return e.run(context.Background(), nil, "read-transcript", "--session-ref", sessionRef)
104	}
105	
106	func (e *Agent) ChunkTranscript(ctx context.Context, content []byte, maxSize int) ([][]byte, error) {
107		stdout, err := e.run(ctx, content, "chunk-transcript", "--max-size", strconv.Itoa(maxSize))
108		if err != nil {
109			return nil, fmt.Errorf("chunk-transcript: %w", err)
110		}
111		var resp ChunkResponse
112		if err := json.Unmarshal(stdout, &resp); err != nil {
113			return nil, fmt.Errorf("chunk-transcript: invalid JSON: %w", err)
114		}
115		return resp.Chunks, nil
116	}
117	
118	func (e *Agent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
119		input, err := json.Marshal(ChunkResponse{Chunks: chunks})
120		if err != nil {
121			return nil, fmt.Errorf("reassemble-transcript: marshal: %w", err)
122		}
123		return e.run(context.Background(), input, "reassemble-transcript")
124	}
125	
126	func (e *Agent) CompactTranscript(ctx context.Context, sessionRef string) (*agent.CompactedTranscript, error) {
127		stdout, err := e.run(ctx, nil, "compact-transcript", "--session-ref", sessionRef)
128		if err != nil {
129			return nil, fmt.Errorf("compact-transcript: %w", err)
130		}
131	
132		var resp CompactTranscriptResponse
133		if err := json.Unmarshal(stdout, &resp); err != nil {
134			return nil, fmt.Errorf("compact-transcript: invalid JSON: %w", err)
135		}
136	
137		compacted, err := resp.toCompactedTranscript()
138		if err != nil {
139			return nil, err
140		}
141		return compacted, nil
142	}
143	
144	// --- Agent interface: Legacy methods ---
145	
146	func (e *Agent) GetSessionID(input *agent.HookInput) string {
147		data, err := marshalHookInput(input)
148		if err != nil {
149			return ""
150		}
151		stdout, err := e.run(context.Background(), data, "get-session-id")
152		if err != nil {
153			return ""
154		}
155		var resp SessionIDResponse
156		if err := json.Unmarshal(stdout, &resp); err != nil {
157			return ""
158		}
159		return resp.SessionID
